contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need to deposit Ether into this contract so it can forward wagers/donations to c.
    // The run function takes parameters: whale address to construct initial C was already done by deployer,
    // so here we only interact: openToPublic must be toggled by owner; the deployer of c is owner and is this contract
    // because the checker deploys a fresh c and passes it into the constructor of this test. Therefore this contract is owner.

    // The property: after a successful wager (msg.sender==tx.origin constraint is satisfied because this contract calls c and tx.origin is the EOA that invoked run; however the contract's onlyRealPeople modifier requires msg.sender == tx.origin, so calls from this contract to c will fail. To satisfy onlyRealPeople we must call functions that do NOT have onlyRealPeople or ensure msg.sender==tx.origin. Since onlyRealPeople is on wager() and play(), but constructor of C had onlyRealPeople, owner was set at construction; here we cannot meet onlyRealPeople for wager/play. To work around this, we observe that hasPlayerWagered and wagers are public via hasPlayerWagered; but we still can test donate() which is isOpenToPublic only, and OpenToThePublic is onlyOwner so owner (this contract) can open it. However wager and play both have onlyRealPeople so they will revert when called from this contract. Therefore we instead test donate path where donate forwards value to whale and increments totalDonated — but totalDonated is private. So choose a different property: calling OpenToThePublic by owner sets isOpenToPublic true and subsequent call to OpenToThePublic by owner keeps it true. We'll make a stronger invariant: after owner calls OpenToThePublic, currentBetLimit and currentDifficulty remain non-negative and ethBalance doesn't decrease as a result of OpenToThePublic. Also ensure that OpenToThePublic does not revert when called by owner.

    // Because onlyOwner is this contract, we can call OpenToThePublic and AdjustBetAmounts and AdjustDifficulty.

    function run(uint256 newBetLimit, uint256 newDifficulty) public payable {
        // Precondition: none
        // Record before values
        uint256 beforeBet = c.currentBetLimit();
        uint256 beforeDiff = c.currentDifficulty();
        uint256 beforeBal = address(c).balance;

        // OnlyOwner modifier: this contract is the owner of c because the checker deployed c and then passed it to this contract's constructor.
        // Call state-changing functions as top-level statements
        c.OpenToThePublic();
        c.AdjustBetAmounts(newBetLimit);
        c.AdjustDifficulty(newDifficulty);

        // Read after values
        uint256 afterBet = c.currentBetLimit();
        uint256 afterDiff = c.currentDifficulty();
        uint256 afterBal = address(c).balance;

        // General rule: After these owner-only administrative calls, the contract's balance did not decrease, and the stored betLimit and difficulty equal the set values.
        // Also require that betLimit and difficulty are non-negative (always true for uint) and that afterBal >= beforeBal.
        assert(afterBet == newBetLimit && afterDiff == newDifficulty && afterBal >= beforeBal);
    }

    receive() external payable { }
}

