contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The single test function: owner (this contract) calls administrative functions.
    // It is payable so the test runner can fund this contract if needed, but we don't forward Ether to c.
    function run(uint256 newBetLimit, uint256 newDifficulty) public payable {
        // This contract is the owner of c because the checker deploys c and then passes it into this test's constructor.
        // Record observable before-values.
        uint256 beforeBal = address(c).balance;
        uint256 beforeBet = c.currentBetLimit();
        uint256 beforeDiff = c.currentDifficulty();

        // Perform the owner-only state changes as top-level statements.
        // These should not revert when called by the owner.
        bool revertedOpen;
        bool revertedBet;
        bool revertedDiff;
        // call OpenToThePublic and capture revert status
        try c.OpenToThePublic() {
            revertedOpen = false;
        } catch {
            revertedOpen = true;
        }
        try c.AdjustBetAmounts(newBetLimit) {
            revertedBet = false;
        } catch {
            revertedBet = true;
        }
        try c.AdjustDifficulty(newDifficulty) {
            revertedDiff = false;
        } catch {
            revertedDiff = true;
        }

        // Read after-values
        uint256 afterBal = address(c).balance;
        uint256 afterBet = c.currentBetLimit();
        uint256 afterDiff = c.currentDifficulty();

        // General invariant to hold for all inputs: when invoked by the owner these admin calls must not revert,
        // they must set betLimit and difficulty to the supplied values, and they must not decrease the contract balance.
        assert(revertedOpen == false && revertedBet == false && revertedDiff == false && afterBet == newBetLimit && afterDiff == newDifficulty && afterBal >= beforeBal);
    }

    // allow receiving Ether if the test environment funds this contract
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: addr is treated as an external EOA (this test contract will call on behalf of that address via direct calls, but msg.sender in calls from this contract is this contract; to simulate a different player we use the contract itself as player because the checker deploys c with this contract as owner — so we instead ensure the caller is a non-owner by first opening to public and using this contract as the player which is the deployer/owner; to make the caller non-owner we rely on the fact that c's owner is the deployer (the checker) so this contract is NOT the owner). 
    // amount is forwarded as Ether to wager and must equal current betLimit to succeed.
    function run(address payable /*unused*/, uint256 amount) public payable {
        // Preconditions for sending Ether
        require(address(this).balance >= amount);

        // Make contract open to public (this contract is NOT the original owner that deployed C in the environment), so this call may revert if not owner; capture revert.
        bool opened;
        try c.OpenToThePublic() {
            opened = true;
        } catch {
            opened = false;
        }

        // Read observable bet limit before attempting to wager
        uint256 bl = c.currentBetLimit();
        // We only proceed with meaningful scenario when OpenToThePublic succeeded and amount equals the reported bet limit and amount > 0
        // The assert at the end is only required to hold for all inputs; we restrict inputs here so the property to prove is applicable.
        require(opened && bl == amount && amount > 0);

        // Record contract balance before
        uint256 beforeBal = address(c).balance;
        // Ensure this contract is not considered a player yet
        bool hadBefore = c.hasPlayerWagered(address(this));

        // Perform the wager call, forwarding amount
        bool revertedWager;
        try c.wager{value: amount}() {
            revertedWager = false;
        } catch {
            revertedWager = true;
        }

        // Read effects after
        uint256 afterBal = address(c).balance;
        bool hasAfter = c.hasPlayerWagered(address(this));

        // General rule: when OpenToThePublic succeeded and we called wager sending exactly currentBetLimit, the call must not revert, the contract balance increases by amount, and the caller is recorded as having wagered.
        assert(revertedWager == false && afterBal == beforeBal + amount && hasAfter == true && hadBefore == false);
    }

    // allow the test harness to fund this contract
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will try to exercise play() and check a general invariant when it does not revert.
    // Parameters:
    //  playerSent - amount to send when calling wager (must equal currentBetLimit to succeed)
    //  dummy - unused address parameter to vary inputs
    function run(address payable /*dummy*/, uint256 playerSent) public payable {
        // allow funding to be forwarded
        require(address(this).balance >= playerSent);

        // Open to public may only succeed if this contract is owner; try regardless and continue even if it fails.
        bool opened;
        try c.OpenToThePublic() {
            opened = true;
        } catch {
            opened = false;
        }

        // Read current bet limit and difficulty (observables)
        uint256 bl = c.currentBetLimit();
        uint256 diff = c.currentDifficulty();

        // We'll only attempt to wager when our provided amount equals the current bet limit and betLimit>0 and difficulty>1
        // Keep this as a precondition on parameters so the execution reaches the main calls.
        require(bl == playerSent && playerSent > 0 && diff > 1);

        // Record winnersPot and hasPlayerWagered before any actions
        uint256 potBefore = c.winnersPot();
        bool hadBefore = c.hasPlayerWagered(address(this));

        // Attempt to wager with the specified amount (may revert)
        bool wagerReverted;
        try c.wager{value: playerSent}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        // Now attempt to call play(). It may revert; capture that.
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // Read observable state after the calls
        uint256 potAfter = c.winnersPot();
        bool hasAfter = c.hasPlayerWagered(address(this));
        uint256 balAfter = address(c).balance;

        // General rule: If play() did not revert, then (1) the caller must have been a player before play (wager succeeded),
        // (2) the caller's recorded wager must be cleared (hasPlayerWagered == false), and
        // (3) the winnersPot is always equal to address(c).balance / 2, so potAfter * 2 <= balAfter*1 (no overflow) —
        //     we assert potAfter * 2 <= balAfter * 1 which enforces winnersPot is at most half the contract balance.
        // We also ensure that if play returned successfully then wager did not revert (i.e., there was a wager to play).
        assert((playReverted == false) ? (wagerReverted == false && hadBefore == true && hasAfter == false && potAfter * 2 <= balAfter) : true);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test donate(): when it returns (does not revert) for an amount 'amt',
    // the contract's balance must decrease by exactly amt (because donate forwards that amount to the whale),
    // and the winnersPot (which is address(c).balance/2) after the call equals (before - amt)/2.
    // We only observe through public surface: winnersPot() and address(c).balance.

    // Single public function taking the donation amount as parameter and sending that Ether.
    function run(uint256 amt) public payable {
        // require we have funds to forward
        require(address(this).balance >= amt);

        // Read observables before the call
        uint256 balBefore = address(c).balance;
        uint256 potBefore = c.winnersPot();

        // Call donate with value amt, capture whether it reverted
        bool donatedReverted;
        try c.donate{value: amt}() {
            donatedReverted = false;
        } catch {
            donatedReverted = true;
        }

        // Read observables after the call
        uint256 balAfter = address(c).balance;
        uint256 potAfter = c.winnersPot();

        // General rule (assert): If donate did not revert then the contract balance decreased by exactly amt
        // and the winnersPot equals address(c).balance/2 (observable) so potAfter * 2 == balAfter.
        // We express the expected balance change: balBefore == balAfter + amt
        assert(donatedReverted || (balBefore == balAfter + amt && potAfter * 2 == balAfter));
    }

    receive() external payable { }
}

