contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We will attempt: open contract, place a wager equal to current bet limit, advance one block by calling a benign tx (can't here), then call play and observe effects.
    // Because the test contract is the one interacting, it is the player and also the deployer of c per harness rules.
    // run takes an amount to fund this test so it can pay wager. It must be exactly the current betLimit when calling wager.
    function run(uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount, "insufficient test funds");
        // Read current bet limit and difficulty and balances before any actions
        uint256 beforeBalance = address(c).balance;
        uint256 betLimit = c.currentBetLimit();
        uint256 difficulty = c.currentDifficulty();
        // To be able to call onlyOwner functions we are not owner; skip. Try to open to public: this will revert if not owner, so we catch and proceed.
        // But to make play/wager succeed we need openToPublic true. The InvMutTest is the deployer of c (per harness), so it is owner and can call OpenToThePublic.
        // Call OpenToThePublic as top-level state-changing call.
        c.OpenToThePublic();
        // Ensure we have exactly betLimit to wager. If betLimit is zero, wagering of zero might be allowed; still test proceeds.
        require(address(this).balance >= betLimit, "not enough to match betLimit");
        // Place wager: must send betLimit
        bool wagerReverted = false;
        try c.wager{value: betLimit}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }
        // If wager reverted, we cannot proceed to play meaningfully; still call play and record revert.
        bool playReverted = false;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }
        uint256 afterBalance = address(c).balance;
        bool playerFlag = c.hasPlayerWagered(address(this));
        uint256 winnersPot = c.winnersPot();
        // Assert general rule: If play succeeded (did not revert) then the player no longer has an active wager (hasPlayerWagered == false)
        // and contract balance decreased by either winnersPot (payout) or by betLimit/2 (loseWager to whale). We express this without relying on who was paid.
        // Note: winnersPot is after the calls; when payout happens it transfers winnersPot (afterBalance already reflects transfer), so change equals beforeBalance - afterBalance.
        // The assert must be general over inputs and observable values. If play reverted or wager reverted, no requirement about those effects is made.
        assert( ( !playReverted && !wagerReverted && !playerFlag && ( (beforeBalance - afterBalance == winnersPot) || (beforeBalance - afterBalance == betLimit / 2) ) )
                || ( playReverted || wagerReverted ) );
    }
    receive() external payable { }
}
